import { MessageChannel, moveMessagePortToContext } from 'node:worker_threads';
import { createContext } from 'node:vm';
function main(): void {
  const channel = new MessageChannel();
  const port1: any = channel.port1;
  const port2: any = channel.port2;
  const ctx: any = createContext({});
  const attempt = (run: () => unknown): string => { try { run(); return 'ok'; } catch (e: any) { return e.name + ' ' + e.code + ' ' + e.message; } };
  const lines: string[] = [];
  lines.push(attempt(() => moveMessagePortToContext()));
  lines.push(attempt(() => moveMessagePortToContext({}, ctx)));
  lines.push(attempt(() => moveMessagePortToContext(port1)));
  lines.push(attempt(() => moveMessagePortToContext(port1, {})));
  lines.push(attempt(() => moveMessagePortToContext(port1, null)));
  lines.push(attempt(() => moveMessagePortToContext(port1, ctx)));
  const closed = new MessageChannel();
  closed.port1.close();
  lines.push(attempt(() => moveMessagePortToContext(closed.port1, ctx)));
  console.log(lines.join('\n'));
  port2.close();
  closed.port2.close();
}
